25	/**
26	 * Per-process counters used by the request-isolation suites. The aggregation
27	 * state itself is per-request; these counters only let tests observe how many
28	 * pipes/handlers ran for a sequence of requests. They are reset in every test's
29	 * beforeEach via {@link resetIsolationState}.
30	 */
31	export const isolationState: {
32	  pipeCalls: string[];
33	  handlerCalls: Record<string, number>;
34	} = {
35	  pipeCalls: [],
36	  handlerCalls: {},
37	};
38	
39	export function resetIsolationState(): void {
40	  isolationState.pipeCalls = [];
41	  isolationState.handlerCalls = {};
42	  MyParamFilter.received = [];
43	  MyWideFilter.last = null;
44	}
45	
46	function recordHandler(name: string): void {
47	  isolationState.handlerCalls[name] =
48	    (isolationState.handlerCalls[name] ?? 0) + 1;
49	}
50	
51	class NumberPipe implements PipeTransform<string, number> {
52	  constructor(private readonly errorMessage: string) {}
53	
54	  transform(value: string): number {
55	    isolationState.pipeCalls.push(this.errorMessage);
56	    const parsed = Number(value);
57	    if (Number.isNaN(parsed) || value.trim() === '') {
58	      throw new BadRequestException(this.errorMessage);
59	    }
60	    return parsed;
61	  }
62	}
63	
64	class SlowNumberPipe implements PipeTransform<
65	  string,
66	  Promise<number> | number
67	> {
68	  constructor(
69	    private readonly errorMessage: string,
70	    private readonly delayMs: number,
71	  ) {}
72	
73	  async transform(value: string): Promise<number> {
74	    isolationState.pipeCalls.push(this.errorMessage);
75	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
76	    const parsed = Number(value);
77	    if (Number.isNaN(parsed) || value.trim() === '') {
78	      throw new BadRequestException(this.errorMessage);
79	    }
80	    return parsed;
81	  }
82	}
83	
84	// The limit chain runs after a DefaultValuePipe, so its input is either the
85	// raw query string or the seeded default number. Explicit invalid values must
86	// fail the chain (LIMIT) instead of silently falling back to the default.
87	class LimitPipe implements PipeTransform<string | number, number> {
88	  transform(value: string | number): number {
89	    isolationState.pipeCalls.push('LIMIT');
90	    if (typeof value === 'string' && value.trim() === '') {
91	      throw new BadRequestException('LIMIT');
92	    }
93	    const parsed = Number(value);
94	    if (Number.isNaN(parsed)) {
95	      throw new BadRequestException('LIMIT');
96	    }
97	    return parsed;
98	  }
99	}
100	
101	class SlowLimitPipe implements PipeTransform<
102	  string | number,
103	  Promise<number> | number
104	> {
105	  constructor(private readonly delayMs: number) {}
106	
107	  async transform(value: string | number): Promise<number> {
108	    isolationState.pipeCalls.push('LIMIT');
109	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
110	    if (typeof value === 'string' && value.trim() === '') {
111	      throw new BadRequestException('LIMIT');
112	    }
113	    const parsed = Number(value);
114	    if (Number.isNaN(parsed)) {
115	      throw new BadRequestException('LIMIT');
116	    }
117	    return parsed;
118	  }
119	}
120	
121	// `currency` is a required query parameter: a missing or blank value is a
122	// request error (CURRENCY), never masked by the optional `limit` default.
123	class CurrencyPipe implements PipeTransform<string | undefined, string> {
124	  transform(value: string | undefined): string {
125	    isolationState.pipeCalls.push('CURRENCY');
126	    if (value === undefined || value.trim() === '') {
127	      throw new BadRequestException('CURRENCY');
128	    }
129	    return value.toUpperCase();
130	  }
131	}
132	
133	// Converts a repeatable `item` query key (`?item=2&item=4`) one element at a
134	// time, in appearance order. Conversion errors are aggregated and stay
135	// indexable (ITEM[0], ITEM[2], ...); `deny` is not a request-parameter error
136	// but a conflict that aborts the resolution immediately.
137	class BatchItemsPipe implements PipeTransform<
138	  string[] | string | undefined,
139	  number[]
140	> {
141	  transform(value: string[] | string | undefined): number[] {
142	    if (value === undefined) {
143	      // The key is entirely absent: one unindexed message, distinct from an
144	      // explicit empty value (which exists as element 0 and fails as ITEM[0]).
145	      isolationState.pipeCalls.push('ITEM');
146	      throw new BadRequestException(['ITEM']);
147	    }
148	    const items = Array.isArray(value) ? value : [value];
149	    const numbers: number[] = [];
150	    const messages: string[] = [];
151	    items.forEach((raw, index) => {
152	      isolationState.pipeCalls.push('ITEM');
153	      if (raw === 'deny') {
154	        // Non-request error: stop touching the remaining elements and abort
155	        // the whole parameter resolution; messages staged earlier are dropped.
156	        throw new ConflictException('DENIED');
157	      }
158	      const parsed = Number(raw);
159	      if (raw.trim() === '' || Number.isNaN(parsed)) {
160	        messages.push(`ITEM[${index}]`);
161	        return;
162	      }
163	      numbers.push(parsed);
164	    });
165	    if (messages.length > 0) {
166	      throw new BadRequestException(messages);
167	    }
168	    return numbers;
169	  }
170	}
171	
172	class NotFoundPipe implements PipeTransform<string, string> {
173	  transform(value: string): string {
174	    isolationState.pipeCalls.push('N');
175	    if (value === 'missing') {
176	      throw new NotFoundException('NOT-FOUND');
177	    }
178	    return value;
179	  }
180	}
181	
182	class PartialAbortPipe implements PipeTransform<string, string> {
183	  transform(value: string): string {
184	    isolationState.pipeCalls.push('M');
185	    if (value === 'abort') {
186	      // A non-BadRequest HttpException: aggregation must abort immediately and
187	      // the default exception layer keeps its regular status/body path.
188	      throw new ForbiddenException('ABORTED');
189	    }
190	    return value;
191	  }
192	}
193	
194	class BodyPipe implements PipeTransform<any, any> {
195	  transform(body: any): any {
196	    isolationState.pipeCalls.push('BODY');
197	    if (!body || body.valid !== true) {
198	      throw new BadRequestException('BODY');
199	    }
200	    return { ...body, transformed: true };
201	  }
202	}
203	
204	class CustomUserPipe implements PipeTransform<any, any> {
205	  transform(user: any): any {
206	    isolationState.pipeCalls.push('CUSTOM');
207	    if (!user || user.ok !== true) {
208	      throw new BadRequestException('CUSTOM');
209	    }
210	    return user;
211	  }
212	}
213	
214	class HeaderNumberPipe implements PipeTransform<string | undefined, number> {
215	  transform(value: string | undefined): number {
216	    isolationState.pipeCalls.push('H');
217	    const parsed = Number(value);
218	    if (
219	      value === undefined ||
220	      String(value).trim() === '' ||
221	      Number.isNaN(parsed)
222	    ) {
223	      throw new BadRequestException('H');
224	    }
225	    return parsed;
226	  }
227	}
228	
229	class HeaderAbortPipe implements PipeTransform<string | undefined, string> {
230	  transform(value: string | undefined): string {
231	    isolationState.pipeCalls.push('HF');
232	    if (value === 'abort') {
233	      // A non-BadRequest exception raised by a header pipe: aggregation must
234	      // abort immediately and the staged param/query messages are discarded.
235	      throw new ForbiddenException('HEADER-ABORT');
236	    }
237	    return value ?? '';
238	  }
239	}
240	
241	// Fail-fast counterpart used by the unannotated compatibility route: it stops
242	// at the first non-convertible element and throws one plain (single) error,
243	// mirroring the legacy short-circuit semantics of any ordinary parameter pipe.
244	class BatchItemsFailFastPipe implements PipeTransform<
245	  string[] | string | undefined,
246	  number[]
247	> {
248	  transform(value: string[] | string | undefined): number[] {
249	    if (value === undefined) {
250	      throw new BadRequestException('ITEM');
251	    }
252	    const items = Array.isArray(value) ? value : [value];
253	    const numbers: number[] = [];
254	    for (let index = 0; index < items.length; index++) {
255	      isolationState.pipeCalls.push('ITEM');
256	      const raw = items[index];
257	      if (raw === 'deny') {
258	        throw new ConflictException('DENIED');
259	      }
260	      const parsed = Number(raw);
261	      if (raw.trim() === '' || Number.isNaN(parsed)) {
262	        throw new BadRequestException(`ITEM[${index}]`);
263	      }
264	      numbers.push(parsed);
265	    }
266	    return numbers;
267	  }
268	}
269	
270	const User = createParamDecorator((_data: unknown, ctx: ExecutionContext) => {
271	  const request = ctx.switchToHttp().getRequest();
272	  const name = request.headers['x-user'];
273	  return name ? { name, ok: true } : { ok: false };
274	});
