276	@Catch(BadRequestException)
277	export class MyParamFilter implements ExceptionFilter {
278	  public static received: Array<{
279	    status: number;
280	    message: unknown;
281	  }> = [];
282	
283	  constructor(private readonly adapterHost: HttpAdapterHost) {}
284	
285	  catch(exception: BadRequestException, host: ArgumentsHost) {
286	    const { httpAdapter } = this.adapterHost;
287	    const response = host.switchToHttp().getResponse();
288	    const responseBody = exception.getResponse() as { message: unknown };
289	    // Record every invocation so tests can assert the filter sees the
290	    // aggregated exception exactly once (never per-parameter exceptions).
291	    MyParamFilter.received.push({
292	      status: exception.getStatus(),
293	      message: responseBody.message,
294	    });
295	    const count = Array.isArray(responseBody.message)
296	      ? responseBody.message.length
297	      : 1;
298	    httpAdapter.reply(response, { code: 'PARAMS_INVALID', count }, 422);
299	  }
300	}
301	
302	@Catch()
303	export class MyWideFilter implements ExceptionFilter {
304	  public static last: { name: string; status?: number } | null = null;
305	
306	  constructor(private readonly adapterHost: HttpAdapterHost) {}
307	
308	  catch(exception: unknown, host: ArgumentsHost) {
309	    const { httpAdapter } = this.adapterHost;
310	    const response = host.switchToHttp().getResponse();
311	    MyWideFilter.last = {
312	      name: (exception as Error)?.name,
313	      status:
314	        typeof (exception as { getStatus?: () => number })?.getStatus ===
315	        'function'
316	          ? (exception as { getStatus: () => number }).getStatus()
317	          : undefined,
318	    };
319	    httpAdapter.reply(response, { code: 'WIDE' }, 418);
320	  }
321	}
