323	@Controller('p')
324	export class AggregateParamErrorsController {
325	  @AggregateParamErrors()
326	  @Get(':id')
327	  public aggregated(
328	    @Param('id', new NumberPipe('A')) id: number,
329	    @Query('limit', new NumberPipe('B')) limit: number,
330	  ) {
331	    recordHandler('aggregated');
332	    return `${id},${limit}`;
333	  }
334	
335	  @Get('legacy/:id')
336	  public legacy(
337	    @Param('id', new NumberPipe('A')) id: number,
338	    @Query('limit', new NumberPipe('B')) limit: number,
339	  ) {
340	    recordHandler('legacy');
341	    return `${id},${limit}`;
342	  }
343	
344	  @AggregateParamErrors()
345	  @UseFilters(MyParamFilter)
346	  @Get('filtered/:id')
347	  public filtered(
348	    @Param('id', new NumberPipe('A')) id: number,
349	    @Query('limit', new NumberPipe('B')) limit: number,
350	  ) {
351	    recordHandler('filtered');
352	    return `${id},${limit}`;
353	  }
354	
355	  @AggregateParamErrors()
356	  @Get('other/:id')
357	  public other(
358	    @Param('id', new NotFoundPipe()) id: string,
359	    @Query('limit', new NumberPipe('B')) limit: number,
360	  ) {
361	    recordHandler('other');
362	    return `${id},${limit}`;
363	  }
364	
365	  // The first @Param() fails with a BadRequest (collected), the second
366	  // @Param() aborts with a non-BadRequest error: the partially collected
367	  // message must die with this request.
368	  @AggregateParamErrors()
369	  @Get('partial/:id/:mode')
370	  public partial(
371	    @Param('id', new NumberPipe('A')) id: number,
372	    @Param('mode', new PartialAbortPipe()) mode: string,
373	    @Query('limit', new NumberPipe('B')) limit: number,
374	  ) {
375	    recordHandler('partial');
376	    return `${id},${mode},${limit}`;
377	  }
378	
379	  // Delayed param pipe used to keep a valid and an invalid request genuinely
380	  // in flight at the same time in the parallel tests.
381	  @AggregateParamErrors()
382	  @Get('slow/:id')
383	  public slow(
384	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
385	    @Query('limit', new NumberPipe('B')) limit: number,
386	  ) {
387	    recordHandler('slow');
388	    return `${id},${limit}`;
389	  }
390	
391	  // @Body() must stay outside the aggregation scope: its pipe error aborts
392	  // immediately even when a @Param() failed first.
393	  @AggregateParamErrors()
394	  @Post('body/:id')
395	  public withBody(
396	    @Param('id', new NumberPipe('A')) id: number,
397	    @Body(new BodyPipe()) body: { transformed: boolean },
398	    @Query('limit', new NumberPipe('B')) limit: number,
399	  ) {
400	    recordHandler('body');
401	    return `${id},${limit},${body.transformed ? 'transformed' : 'raw'}`;
402	  }
403	
404	  // Custom parameter extractors must keep the existing (fail-fast) scope.
405	  @AggregateParamErrors()
406	  @Get('custom/:id')
407	  public withCustom(
408	    @Param('id', new NumberPipe('A')) id: number,
409	    @User(new CustomUserPipe()) user: { name: string },
410	    @Query('limit', new NumberPipe('B')) limit: number,
411	  ) {
412	    recordHandler('custom');
413	    return `${id},${limit},${user.name}`;
414	  }
415	
416	  // @Headers() parameters are an independent input domain: the header pipe
417	  // always runs and its transformed value reaches the handler, but a header
418	  // failure aborts the resolution immediately and discards any @Param()/
419	  // @Query() messages collected so far.
420	  @AggregateParamErrors()
421	  @Get('headers/:id')
422	  public withHeaders(
423	    @Param('id', new NumberPipe('A')) id: number,
424	    @Headers('x-token', new HeaderNumberPipe()) token: number,
425	    @Query('limit', new NumberPipe('B')) limit: number,
426	  ) {
427	    recordHandler('headers');
428	    return `${id},${token},${limit}`;
429	  }
430	
431	  // The filter must observe only the header exception when the header pipe
432	  // fails - never the staged @Param()/@Query() messages.
433	  @AggregateParamErrors()
434	  @UseFilters(MyParamFilter)
435	  @Get('headers-filtered/:id')
436	  public withHeadersFiltered(
437	    @Param('id', new NumberPipe('A')) id: number,
438	    @Headers('x-token', new HeaderNumberPipe()) token: number,
439	    @Query('limit', new NumberPipe('B')) limit: number,
440	  ) {
441	    recordHandler('headersFiltered');
442	    return `${id},${token},${limit}`;
443	  }
444	
445	  // A non-BadRequest header exception propagates unchanged through the
446	  // catch-all filter; the staged param/query messages die with the request.
447	  @AggregateParamErrors()
448	  @UseFilters(MyWideFilter)
449	  @Get('headers-wide/:id')
450	  public withHeadersWide(
451	    @Param('id', new NumberPipe('A')) id: number,
452	    @Headers('x-mode', new HeaderAbortPipe()) mode: string,
453	    @Query('limit', new NumberPipe('B')) limit: number,
454	  ) {
455	    recordHandler('headersWide');
456	    return `${id},${mode},${limit}`;
457	  }
458	
459	  // Unannotated route with a header pipe: the header pipe runs, but the
460	  // fail-fast compatibility path is unchanged.
461	  @Get('headers-legacy/:id')
462	  public withHeadersLegacy(
463	    @Param('id', new NumberPipe('A')) id: number,
464	    @Headers('x-token', new HeaderNumberPipe()) token: number,
465	    @Query('limit', new NumberPipe('B')) limit: number,
466	  ) {
467	    recordHandler('headersLegacy');
468	    return `${id},${token},${limit}`;
469	  }
470	
471	  // Delayed pipes on all three domains, used to keep mixed-failure requests
472	  // genuinely in flight at the same time in the parallel tests.
473	  @AggregateParamErrors()
474	  @Get('headers-slow/:id')
475	  public withHeadersSlow(
476	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
477	    @Headers('x-token', new SlowNumberPipe('H', 30)) token: number,
478	    @Query('limit', new SlowNumberPipe('B', 30)) limit: number,
479	  ) {
480	    recordHandler('headersSlow');
481	    return `${id},${token},${limit}`;
482	  }
483	
484	  // A catch-all method filter must receive the original non-request exception
485	  // unchanged (not the aggregated BadRequest).
486	  @AggregateParamErrors()
487	  @UseFilters(MyWideFilter)
488	  @Get('wide/:id')
489	  public wide(
490	    @Param('id', new NotFoundPipe()) id: string,
491	    @Query('limit', new NumberPipe('B')) limit: number,
492	  ) {
493	    recordHandler('wide');
494	    return `${id},${limit}`;
495	  }
496	
497	  // Optional query value with a per-resolution default: when `limit` is
498	  // absent, DefaultValuePipe seeds 10 which still runs through the same
499	  // LimitPipe conversion as an explicit value. An explicit invalid value
500	  // must fail (LIMIT), never fall back to 10. `currency` is required.
501	  @AggregateParamErrors()
502	  @Get('defaults/:id')
503	  public defaults(
504	    @Param('id', new NumberPipe('A')) id: number,
505	    @Query('currency', new CurrencyPipe()) currency: string,
506	    @Query('limit', new DefaultValuePipe(10), new LimitPipe())
507	    limit: number,
508	  ) {
509	    recordHandler('defaults');
510	    return { id, currency, limit };
511	  }
512	
513	  // Delayed variant of the defaults route used to keep a default-success and
514	  // an explicit-invalid request genuinely in flight in the parallel tests.
515	  @AggregateParamErrors()
516	  @Get('defaults-slow/:id')
517	  public defaultsSlow(
518	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
519	    @Query('currency', new CurrencyPipe()) currency: string,
520	    @Query('limit', new DefaultValuePipe(10), new SlowLimitPipe(30))
521	    limit: number,
522	  ) {
523	    recordHandler('defaultsSlow');
524	    return { id, currency, limit };
525	  }
526	}
527	
528	// Root-level controller for the repeatable-query-key batch routes. The marked
529	// route aggregates the per-element conversion feedback of a single request;
530	// the unannotated route keeps the legacy fail-fast short-circuit for contrast.
531	@Controller()
532	export class BatchController {
533	  @AggregateParamErrors()
534	  @Get('batch/:id')
535	  public batch(
536	    @Param('id', new NumberPipe('A')) id: number,
537	    @Query('item', new BatchItemsPipe()) items: number[],
538	  ) {
539	    recordHandler('batch');
540	    return { id, items };
541	  }
542	
543	  @Get('batch-legacy/:id')
544	  public batchLegacy(
545	    @Param('id', new NumberPipe('A')) id: number,
546	    @Query('item', new BatchItemsFailFastPipe()) items: number[],
547	  ) {
548	    recordHandler('batchLegacy');
549	    return { id, items };
550	  }
551	}
